class ScriptedRun:
    def __init__(self):
        self.rules = []
        self.calls = []

    def when(self, predicate, proc):
        self.rules.append((predicate, proc))
        return self

    def __call__(self, argv, env=None, cwd=None, check=True, capture_output=True, input_text=None):
