      fi
    else
      fail "30: ${name}: second helm template render failed"
      cat "${WORKDIR}/${name}-second-render.err"
    fi
  done <<< "$(python3 -c "
import yaml
doc = yaml.safe_load(open('${CANONICAL_CONFIG}'))
for d in doc['deployments']:
    if d.get('enabled'):
        print(d['name'])
")"
