  set +e
  MALFORMED_CURRENT_OUTPUT="$(cd "$MALFORMED_REPO" && bash -c '
    set -euo pipefail
    source "'"${WORKDIR}"'/is_gg_fn.sh"
    source "'"${WORKDIR}"'/is_active_fn.sh"
    jq() { echo "[SHOULD_NOT_BE_CALLED]"; }
    BEFORE_SHA="'"$MALFORMED_BEFORE_SHA"'"
    DELETION_MATRIX_ITEMS="[]"
    INACTIVE_LOG=""
