r = simulate(ctx, {}, {"argocd_preflight": {"state": "OWNED"}, "platform_preflight": {"state": "OWNED"}, "observability_preflight": {"state": "OWNED"}, "runtime_ownership_preflight": {"state": "OWNED"}})
