    --set-string argocdServerIngress.groupName=gg-poc-dev-alb
    --set-string argocdServerIngress.certificateArn=arn:aws:acm:eu-west-1:668311715351:certificate/9e53e28e-3243-47fc-85a1-50f9a94acde7
  )

